-- suite test: t_m40 (auto-generated by hand, shared boilerplate)
local frame = 0
local t = 0
local function inject(keys)
  for i = 1, #keys do
    emu.write16(0x7E0700 + t, 0x1000 + keys:byte(i), emu.memType.snesMemory)
    t = (t + 2) % 64
  end
  emu.write16(0x7E00D8, t, emu.memType.snesMemory)
end
local function bufhas(str)
  for r = 0, 24 do
    local s = ""
    for c = 0, 79 do
      local ch = emu.read(0x7E1000 + r*160 + c*2, emu.memType.snesMemory)
      if ch < 32 or ch > 126 then ch = 32 end
      s = s .. string.char(ch)
    end
    if s:find(str, 1, true) then return true end
  end
  return false
end
local function bufbyte2(b1, b2)
  for r = 0, 24 do
    for c = 0, 78 do
      if emu.read(0x7E1000 + r*160 + c*2, emu.memType.snesMemory) == b1 and
         emu.read(0x7E1000 + r*160 + (c+1)*2, emu.memType.snesMemory) == b2 then
        return true
      end
    end
  end
  return false
end
local function booted()
  return bufhas("C:\\>")
end

-- Adaptive (the t_zork pattern): advance on screen/machine state, not fixed
-- frame numbers - boot time drifts as the C: image evolves.
local function cwid()
  return emu.read16(0x7E078C, emu.memType.snesMemory)
end
local stage = 0
emu.addEventCallback(function()
  frame = frame + 1
  if stage == 0 and frame > 600 and frame % 30 == 0 and booted() then
    inject("mode 40\r"); stage = 1
  elseif stage == 1 and frame % 30 == 0 and cwid() == 40 then
    inject("mode 80\r"); stage = 2
  elseif stage == 2 and frame % 30 == 0 and cwid() == 80 then
    print("RESULT PASS t_m40"); emu.stop(0)
  end
  if frame == 12000 then
    print("RESULT FAIL t_m40 (stage=" .. stage .. " cWID=" .. cwid() .. ")")
    emu.stop(0)
  end
end, emu.eventType.endFrame)
